L000002	\begin{algorithm}
L000003	\caption{Camera Localization using Static Hidden Object}
L000004	\begin{algorithmic}[1]
L000005	
L000006	
L000007	\State \textbf{Input:} number of particles $K$, space-time measurements $i_{1:T} \in \mathbb{R}^{n_xn_y \times n_v}$, point clouds in camera coordinates $p_{1:T} \in \mathbb{R}^{n_xn_y \times 3}$, canonical STIR of hidden object $\hat{\mathcal{I}}(x, y, v) \in \mathbb{R}^{N_x \times N_y \times N_v}$
L000008	
L000009	\State \textbf{Output:} posterior distribution over $(x, y)$ camera locations $\mathbf{c}_{1:T} \in \mathbb{R}^{K \times 2}$, camera $z$ positions $z_{1:T}$
L000010	
L000011	\State
L000012	
L000013	
L000014	\State \textbf{\# === Initialize particles at $t=1$ from 2D uniform distribution === \#}
L000015	
L000016	\State $\{\mathbf{c}_{t=1,k}\}_{k=1}^K \gets \mathcal{U}\left([x_{\min}, x_{\max}] \times [y_{\min}, y_{\max}]\right) $ \Comment{$K \times 2$ uniform matrix}
L000017	
L000018	\State
L000019	
L000020	
L000021	
L000022	\State \textbf{\# === Loop through frames === \#}
L000023	\For{$t = 1$ to $T$}
L000024	
L000025	    \State \textbf{\# Fit point cloud to $z=0$ to compute point cloud and camera $z$ position}
L000026	    \State $z_t, p_t \gets \text{fit\_plane}(p_t)$
L000027	
L000028	    \State
L000029	
L000030	
L000031	    \State \textbf{\# Evaluate particles (data likelihood)}
L000032	    \For{$k = 1$ to $K$}
L000033	
L000034	        \State $p_{t, k}[:, 0] \gets p_t[:, 0] + \mathbf{c}_k[0]$ \Comment{$x$ point cloud shift}
L000035	         \State $p_{t, k}[:, 1] \gets p_t[:, 1] + \mathbf{c}_k[1]$ \Comment{$y$ point cloud shift}
L000036	
L000037	        \State $\hat{i}_{t,k} \gets \text{render}(\hat{\mathcal{I}}, p_{t,k}, 0)$ \Comment{render with no object shift (Eq. 3)}
L000038	
L000039	        \State $w_k \gets \text{dot\_product\_score}(i_t, \hat{i}_{t,k})$  \Comment{score function (Eq. 10)}
L000040	    \EndFor
L000041	
L000042	
L000043	    \State  $w_{t,k} \gets \frac{w_{t,k}}{\sum_{j=1}^N w_{t,j}}$ \Comment{normalize particle scores}
L000044	
L000045	    \State
L000046	
L000047	
L000048	    \State \textbf{\# Resample particles based on particle weights}
L000049	    \State
L000050	    $\{\mathbf{c}_{t,k}\}_{k=1}^K \gets \text{residual\_resampling}(\{\mathbf{c}_{t,k}, w_{t,k}\}_{k=1}^K)$
L000051	
L000052	
L000053	    \State
L000054	    \State \textbf{\# Propagate particles for next frame (motion model)}
L000055	    \State $\{\mathbf{c}_{t+1,k}\}_{k=1}^K \gets \mathcal{N}(\mathbf{c}_{t,k}, r\mathbf{I})$
L000056	
L000057	\EndFor
L000058	\end{algorithmic}
L000059	\label{alg:localization}
L000060	
L000061	\end{algorithm}
L000062	===== END FILE: algorithms/localization.tex =====
L000063	
L000064	===== BEGIN FILE: algorithms/tracking.tex =====
L000065	\begin{algorithm}
L000066	\caption{Single and Multi-Object Tracking with Known Pose and Object Shape(s)}
L000067	\begin{algorithmic}[1]
L000068	
L000069	\State \textbf{Input:} number of particles $K$, space-time measurements $i_{1:T} \in \mathbb{R}^{n_xn_y \times n_v}$, point clouds in world coordinates $p_{1:T} \in \mathbb{R}^{n_xn_y \times 3}$, canonical STIR of $M$ hidden objects $\{\hat{\mathcal{I}}_1(x, y, v),...,\hat{\mathcal{I}}_M(x, y, v)\} \in \mathbb{R}^{N_x \times N_y \times N_v}$
L000070	
L000071	\State \textbf{Output:} posterior distribution over $(x, y, z)$ object positions $\mathbf{\Delta}_{1:T} \in \mathbb{R}^{K \times 3M}$
L000072	
L000073	\State
L000074	
L000075	
L000076	\State \textbf{\# === Initialize particles at $t=0$ from $3M$-D uniform distribution === \#}
L000077	
L000078	
L000079	
L000080	\State $\{\{\mathbf{\Delta}_{t=1,k,m}\}_{k=1}^K\}_{m=1}^M \gets \mathcal{U}\left([x_{\min}, x_{\max}] \times [y_{\min}, y_{\max}] \times [z_{\min}, z_{\max}] \right) $ \Comment{$K \times 3M$ uniform matrix}
L000081	
L000082	\State
L000083	
L000084	
L000085	
L000086	\State \textbf{\# === Loop through frames === \#}
L000087	\For{$t = 1$ to $T$}
L000088	
L000089	    \State \textbf{\# Transform measurements using LCT}
L000090	    \State $i_t \gets \text{transform\_measurements}(i_t)$
L000091	
L000092	    \State
L000093	
L000094	    \State \textbf{\# Evaluate particles (data likelihood)}
L000095	    \For{$k = 1$ to $K$}
L000096	        \State initialize $\hat{i}_{t,k} \gets 0$
L000097	        \For{$m = 1$ to $M$}
L000098	
L000099	            \State $\hat{i}_{t,k} \gets \hat{i}_{t,k} + \text{render}(\hat{\mathcal{I}}_m, p_t, \mathbf{\Delta}_{m,k})$ \Comment{Eq. 3}
L000100	        \EndFor
L000101	
L000102	        \State $w_{t,k} \gets \text{dot\_product\_score}(i_t, \hat{i}_{t,k})$  \Comment{Eq. 10}
L000103	    \EndFor
L000104	
L000105	
L000106	    \State  $w_{t,k} \gets \frac{w_{t,k}}{\sum_{j=1}^N w_{t,j}}$ \Comment{normalize particle scores}
L000107	
L000108	    \State
L000109	
L000110	
L000111	    \State \textbf{\# Resample particles based on particle weights}
L000112	    \State
L000113	    $\{\mathbf{\Delta}_{t,k}\}_{k=1}^K \gets \text{residual\_resampling}(\{\mathbf{\Delta}_{t,k}, w_{t,k}\}_{k=1}^K)$
L000114	
L000115	
L000116	    \State
L000117	    \State \textbf{\# Propagate particles for next frame (motion model)}
L000118	
L000119	    \State $\mathbf{\Delta}_{t+1,k} \gets \mathcal{N}(\mathbf{\Delta}_{t,k}, r\mathbf{I})$
L000120	
L000121	\EndFor
L000122	\end{algorithmic}
L000123	\label{alg:tracking}
L000124	
L000125	\end{algorithm}
L000126	===== END FILE: algorithms/tracking.tex =====
