L000967	\section{Derivation of Motion-Induced Aperture Sampling Model}
L000968	
L000969	\paragraph{Primer on Light-Cone Transform.}
L000970	
L000971	Our NLOS setup consists of a planar relay wall that lies along the $z=0$ plane. Under a confocal setup with a static object, the measured intensity at a point on the wall $(x, y, z=0)$ and time $\tau$ can be expressed as
L000972	
L000973	\begin{equation}
L000974	    i(x,y,\tau) = \iiint_\Omega \frac{\rho(x', y', z')}{r(x',y',z')^4}\cdot \delta(2r(x', y', z')-c\tau)dx'dy'dz',
L000975	    \label{eq:cnlos_forward_model}
L000976	\end{equation}
L000977	
L000978	\noindent where $\rho(x', y', z')$ is the volumetric albedo of the hidden scene, $r(x', y', z') =\sqrt{(x-x')^2 + (y-y')^2 + {z'}^2}$, $c$ is the speed of light, $\delta(\cdot)$ is the Dirac delta function, and the integral is over the 3D hidden volume. This model assumes diffuse reflectance, but can also be modified to account for retroreflective objects by changing the $r^4$ term to $r^2$. After applying a change of variables $z'=\sqrt{u}$ and $v=(ct/2)^2$, noting that $r(x', y', z') = (ct/2) = \sqrt{v}$, and using properties of Dirac delta functions, \cref{eq:cnlos_forward_model} becomes
L000979	
L000980	\begin{equation}
L000981	    \underbrace{v^{3/2} \tau(x, y, \frac{2\sqrt{v}}{c})}_{\mathcal{R}_t\{\tau\}(x, y, v)} = \iiint_\Omega \underbrace{\frac{\rho(x', y', \sqrt{u})}{2\sqrt{u}}}_{\mathcal{R}_z\{\rho\}(x, y, u)} \cdot \underbrace{\delta((x-x')^2+(y-y')^2+u-v)}_{h(x-x', y-y', v-u)}dx'dy'du,
L000982	    \label{eq:lct_full}
L000983	\end{equation}
L000984	
L000985	\noindent where $\mathcal{R}_t$ and $\mathcal{R}_z$ are non-linear resampling and attenuation operators along $t$ in the measurement space and $z$ in the albedo space. $\mathcal{R}_t$ transforms the time axis of the measurement as $v=(ct/2)^2$ and scales the measurement intensity by $v^{3/2}=(ct/2)^3$. $\mathcal{R}_z$ transforms the depth axis of the hidden volume as $u=z^2$ and scales the albedo by $1/2\sqrt{u}=1/2z$. \cref{eq:lct_full} defines the light-cone transform (LCT) \cite{o2018confocal}, and has convolutional form in a transformed measurement and object space
L000986	
L000987	
L000988	\begin{align}
L000989	    \mathcal{I}(x, y, v) =  \mathcal{Q}(x, y, v) \circledast h(x, y, v),
L000990	    \label{eq:lct}
L000991	\end{align}
L000992	
L000993	\noindent where $\mathcal{Q} = \mathcal{R}_z\{\rho\}$ and $\mathcal{I} = \mathcal{R}_t\{i\}$. The LCT performs a 3D convolution in $x$, $y$, and the transformed variable $v$. $v$ refers to the transformed version of the $t$ axis of the measurement $i$ and the $z$ axis of the volumetric albedo $\rho$. In transforming these two dimensions, $t$ and $z$, the LCT aligns time and space to make 3D convolution mathematically coherent. We leverage this convolutional relationship between the measurements $\tau$ and object $\rho$ in the LCT-transformed space to develop our motion model.
L000994	
L000995	
L000996	
L000997	
L000998	
L000999	
L001000	
L001001	\paragraph{Effect of Object Motion.}
L001002	\label{sec:object_motion}
L001003	We now consider the effect that object translation\footnote{We don't consider rotation in this work, though our model could be extended to roll rotation parallel to the wall.} has on the space-time impulse response $\mathcal{I}(x, y, v)$. An object with shape $\rho(x, y, z) \xLeftrightarrow{\text{LCT}} Q(x, y, v)$ has an impulse response $\mathcal{I}_0(x, y, v)$ as defined by \cref{eq:lct}. We refer to $\mathcal{I}_0(x, y, v)$ as the canonical response of the object.
L001004	
L001005	We approximate the object's shape as a set of points $\mathcal{P}$, where each point $p$ has an albedo $\rho_p$. Therefore, the object shape can be modeled as
L001006	
L001007	\begin{equation}
L001008	    \rho(\mathbf{x}_p, z) \approx \sum_{p \in \mathcal{P}} \rho_p \cdot \delta(\mathbf{x}-\mathbf{x}_p, z-z_p),
L001009	\end{equation}
L001010	
L001011	\noindent where $\mathbf{x}=(x, y)$ and $\mathbf{x}_p=(x_p, y_p)$. Using this parametrization of the object shape and neglecting self-occlusions, the impulse response in LCT space is
L001012	
L001013	\begin{equation}
L001014	    \mathcal{I}_0(\mathbf{x}, v)= \left[ \sum_{p \in \mathcal{P}} \frac{\rho_p}{2\sqrt{v_p}} \cdot \delta(\mathbf{x}-\mathbf{x}_p, v-v_p)\right] \circledast h(\mathbf{x}, v),
L001015	\end{equation}
L001016	
L001017	\noindent where $v_p = z_p^2$. Assuming a rigid-body object translation of $\mathbf{\Delta}=(\Delta_x, \Delta_y, \Delta_z)$, each point on the object will move by the same amount $\mathbf{\Delta}$. As a result, the impulse response after object translation can be expressed as
L001018	
L001019	\begin{align}
L001020	    \mathcal{I}(\mathbf{x}, v) &= \left[ \sum_{p \in \mathcal{P}} \frac{\rho_p}{2\sqrt{v_p + \Delta_v}} \cdot \delta(\mathbf{x}-\mathbf{x}_p-\mathbf{\Delta}_x, v-v_p-\Delta_v) \right] \circledast h(\mathbf{x}, v) \\
L001021	    &\approx \left[ \sum_{p \in \mathcal{P}} \frac{\rho_p}{2\sqrt{v_p}} \cdot \delta(\mathbf{x}-\mathbf{x}_p-\mathbf{\Delta}_x, v-v_p-\Delta_v) \right] \circledast h(\mathbf{x}, v) \\
L001022	    &= \left[ \sum_{p \in \mathcal{P}} \frac{\rho_p}{2\sqrt{v_p}} \cdot \delta(\mathbf{x}-\mathbf{x}_p, v-v_p) \circledast \delta(\mathbf{x}-\mathbf{\Delta}_x, v-\Delta_v) \right] \circledast h(\mathbf{x}, v) \\
L001023	    &= \left[ \sum_{p \in \mathcal{P}} \frac{\rho_p}{2\sqrt{v_p}} \cdot \delta(\mathbf{x}-\mathbf{x}_p, v-v_p) \right] \circledast \delta(\mathbf{x}-\mathbf{\Delta}_x, v-\Delta_v) \circledast h(\mathbf{x}, v) \\
L001024	    \label{eq:tracking_as_convolution}
L001025	    &= \mathcal{I}_0(\mathbf{x}, v) \circledast \delta(\mathbf{x}-\mathbf{\Delta}_x, v-\Delta_v)  \\
L001026	    &= \mathcal{I}_0(\mathbf{x}-\mathbf{\Delta}_x, v-\Delta_v),
L001027	\end{align}
L001028	
L001029	\noindent where the second line assumes $\Delta_v << v_p$ and fourth line uses the linearity of the convolution operation. While the assumption in the second line is often not accurate, it only results in a radiometric distortion and has no effect on the shape of the space-time measurement. Therefore, we ignore it. Based on this derivation, the premise is straightforward: a shift in the object position results in a shift of the canonical measurement $\mathcal{I}_0$. The canonical response defines the impulse response at a reference object position (ideally the world coordinates origin). Any object position can be expressed with respect to the reference position defined by the canonical response. If the reference position is at $z=0$, then $\Delta_v$ would correspond to the distance of the object from the wall, and we can directly compute the $z$ displacement as $z=\sqrt{\Delta_v}$.
